const assert = require('assert');
const { TaskQueue } = require('./taskqueue.js');

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

(async () => {
  const q = new TaskQueue();
  const events = [];
  let running = 0;
  let maxConcurrent = 0;
  q.on('result', (i, v) => events.push(['result', i, v]));
  q.on('failure', (i, e) => events.push(['failure', i, e.message]));

  const drained = new Promise((resolve) => q.on('drain', resolve));

  const track = (fn) => async () => {
    running += 1;
    maxConcurrent = Math.max(maxConcurrent, running);
    try { return await fn(); } finally { running -= 1; }
  };

  q.add(track(async () => { await sleep(30); return 'a'; }));
  q.add(track(async () => { throw new Error('boom'); }));
  q.add(track(async () => 'c'));

  const values = await drained;
  assert.strictEqual(maxConcurrent, 1, 'tasks must run one at a time');
  assert.deepStrictEqual(events, [
    ['result', 0, 'a'],
    ['failure', 1, 'boom'],
    ['result', 2, 'c'],
  ], `event order/payloads wrong: ${JSON.stringify(events)}`);
  assert.deepStrictEqual(values, ['a', null, 'c'], 'drain payload wrong');
  console.log('PASS');
})().catch((e) => { console.error(e); process.exit(1); });

