const { EventEmitter } = require('events');

class TaskQueue extends EventEmitter {
  constructor() {
    super();
    this._tasks = [];
    this._results = [];
    this._running = false;
  }

  add(fn) {
    this._tasks.push(fn);
    if (!this._running) {
      this._running = true;
      setImmediate(() => this._run());
    }
    return this;
  }

  async _run() {
    let index = 0;
    while (index < this._tasks.length) {
      const fn = this._tasks[index];
      try {
        const value = await fn();
        this._results[index] = value;
        this.emit('result', index, value);
      } catch (err) {
        this._results[index] = null;
        this.emit('failure', index, err);
      }
      index += 1;
    }
    this._running = false;
    this.emit('drain', this._results);
  }
}

module.exports = { TaskQueue };

