const { EventEmitter } = require('events');

class TaskQueue extends EventEmitter {
  constructor() {
    super();
    this._pending = [];
    this._results = [];
    this._count = 0;
  }

  add(fn) {
    const index = this._count++;
    const p = Promise.resolve()
      .then(fn)
      .then((value) => {
        this._results[index] = value;
        this.emit('result', index, value);
      })
      .catch((err) => {
        this._results[index] = null;
        this.emit('failure', index, err);
      });
    this._pending.push(p);
    setImmediate(() => {
      Promise.all(this._pending).then(() => {
        if (!this._drained) {
          this._drained = true;
          this.emit('drain', this._results);
        }
      });
    });
    return this;
  }
}

module.exports = { TaskQueue };
